interface SpacingSelector {
  selector: string;
  property: string;
  modifier: string;
  value: string;
}

export const getSpacingSelectors = (
  property: string,
  sides: string[],
  spaces: any,
  shortSides?: string
): SpacingSelector[] => {
  const result: SpacingSelector[] = [];

  sides.map(side => {
    const sideString = shortSides
      ? `${property.charAt(0)}${side.charAt(0)}`
      : side;

    Object.keys(spaces).map(space => {
      result.push({
        selector: sideString,
        property: `${property}${
          side && property ? `-${side}` : side ? side : ''
        }`,
        modifier: space,
        value:
          space === 'auto' || space === '0'
            ? space
            : `var(--lns-space-${space})`,
      });
    });
  });

  return result;
};

export const marginRules = Object.values(
  getSpacingSelectors(
    'margin',
    ['', ...sides],
    spacesWithAutoAndZero,
    'shortSides'
  )
).map(spaceSelector => {
  return {
    selector: spaceSelector.selector,
    modifier: spaceSelector.modifier,
    declarations: [
      {
        property: spaceSelector.property,
        value: spaceSelector.value,
      },
    ],
  };
});

export const marginCrossRules = Object.values(
  getSpacingSelectors('margin', ['x', 'y'], spacesWithAutoAndZero, 'shortSides')
).map(spaceSelector => {
  return {
    selector: spaceSelector.selector,
    modifier: spaceSelector.modifier,
    declarations: [
      {
        property:
          spaceSelector.property === 'margin-x' ? 'margin-left' : 'margin-top',
        value: spaceSelector.value,
      },
      {
        property:
          spaceSelector.property === 'margin-x'
            ? 'margin-right'
            : 'margin-bottom',
        value: spaceSelector.value,
      },
    ],
  };
});

