export const borderRules = ['', ...sides].map(side => {
  const selector =
    'border' + side.replace(side.charAt(0), side.charAt(0).toUpperCase());

  const property = `border${side && `-${side}`}`;

  return {
    selector,
    declarations: [
      {
        property,
        value: `1px solid var(--lns-color-border)`,
      },
    ],
  };
});

