import styled from '@emotion/styled';
import React from 'react';

import { SvgSearch } from '../icon/available-icons/search';
import TextInput from '../text-input/text-input';
import { u } from '../../utilities';

const SearchBarContainer = styled.div`
  padding: ${u(1.5)} ${u(1.5)} 0;
  margin-bottom: ${u(1.5)};
  position: sticky;
  top: 0;
`;

const SearchBar = ({
  ariaLabel,
  placeholder,
  value,
  onChange,
  getInputProps,
}: {
  ariaLabel: string;
  placeholder: string;
  value: string;
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  getInputProps?: any;
}) => {
  return (
    <SearchBarContainer>
      <TextInput
        aria-label={ariaLabel}
        icon={<SvgSearch />}
        {...getInputProps({
          placeholder,
          value,
          onChange,
          type: 'text',
        })}
      />
    </SearchBarContainer>
  );
};

export default SearchBar;
