const LogoWrapper = styled.span<LogoWrapperProps>`
  display: block;
  ${props => props.maxWidth && getSize('max-width', props.maxWidth)};

  & > svg.lns-logoSvg {
    display: block;
    width: 100%;
    height: 100%;
    ${props => props.maxWidth && getSize('max-width', props.maxWidth)};
  }
`;

const Logo = ({
  variant = 'combined',
  maxWidth,
  symbolColor,
  wordmarkColor = 'body',
  brand = 'loom',
  customId = '',
  ...props
}: LogoProps &
  React.ComponentProps<typeof LogoWrapper> &
  Omit<
    LensSpanProps,
    keyof LogoProps & React.ComponentProps<typeof LogoWrapper>
  >) => (
  <LogoWrapper variant={variant} maxWidth={maxWidth} {...props}>
    {variant === 'combined' && (
      <CombinedLogoSvg
        brand={brand}
        symbolColor={symbolColor}
        wordmarkColor={getColorValue(wordmarkColor)}
        customId={customId}
        className="lns-logoSvg"
      />
    )}
    {variant === 'symbol' && (
      <SymbolLogoSvg
        brand={brand}
        symbolColor={symbolColor}
        customId={customId}
        className="lns-logoSvg"
      />
    )}
    {variant === 'wordmark' && (
      <WordmarkLogoSvg
        brand={brand}
        wordmarkColor={getColorValue(wordmarkColor)}
        className="lns-logoSvg"
      />
    )}
  </LogoWrapper>
);

export const availableVariants = ['combined', 'symbol', 'wordmark'];

type LogoProps = {
  variant?: 'combined' | 'symbol' | 'wordmark';
  brand?: 'loom' | 'ai' | 'apptile' | 'product' | 'marketing' | 'attributed';
  maxWidth?: number | string;
  symbolColor?: string;
  wordmarkColor?: string;
  customId?: string;
};

type LogoWrapperProps = {
  variant?: 'combined' | 'symbol' | 'wordmark';
  brand?: 'loom' | 'ai' | 'apptile' | 'product' | 'marketing' | 'attributed';
  maxWidth?: number | string;
};

export default Logo;
