type ThemesColorVariant = Record<
  (typeof SharedColors)[number] | (typeof SemanticColors)[number],
  HslaColor
>;
type ThemesColors = {
  light: ThemesColorVariant;
  dark: ThemesColorVariant;
};

const percent = (number: number, percentage: number) =>
  Math.round((number * percentage) / 100);

export const darken = (color: HslaColor, percentage: number): HslaColor => ({
  ...color,
  l: color.l - percent(color.l, percentage),
});

export const lighten = (color: HslaColor, percentage: number): HslaColor => ({
  ...color,
  l: color.l + percent(color.l, percentage),
});

export const saturate = (color: HslaColor, percentage: number): HslaColor => ({
  ...color,
  s: color.s + percent(color.s, percentage),
});

export const alphaFunction = (color: HslaColor, alpha: number): HslaColor => ({
  ...color,
  a: alpha,
});

